<?php declare(strict_types=1); require_once dirname(__DIR__,2).'/lib/tool-page.php'; $tool=['title'=>'Free Username Generator Online','description'=>'Generate random usernames from words and numbers instantly.','url'=>'https://smarttoolz.in/tools/username-generator/']; smarttoolz_tool_page_start($tool); ?><main class="tool-page"><section class="tool-intro"><span class="tool-kicker">USERNAME GENERATOR</span><h1>Username Generator</h1><p>Create random username ideas for apps, games and social profiles.</p></section><section class="tool-workspace"><div class="tool-panel"><label>How many?<input id="n" type="number" min="1" max="50" value="10"></label><button id="go" class="tool-btn">Generate Usernames</button><textarea id="out" rows="12" readonly style="margin-top:15px;width:100%;box-sizing:border-box"></textarea><button id="copy" class="tool-btn" style="margin-top:10px">Copy All</button></div></section></main><script>(()=>{const a=['swift','pixel','smart','nova','code','bright','cloud','craft','orbit','tech','daily','zen'],o=document.getElementById('out'),n=document.getElementById('n');document.getElementById('go').onclick=()=>o.value=Array.from({length:Math.min(50,Math.max(1,+n.value||1))},()=>a[Math.random()*a.length|0]+a[Math.random()*a.length|0]+(Math.random()*1000|0)).join('\n');document.getElementById('copy').onclick=()=>navigator.clipboard.writeText(o.value);document.getElementById('go').click()})();</script><?php smarttoolz_tool_page_end(); ?>